Definition chn_0RB1LC_0LC1RD_1RB1LA_0RB0RB : list lstep := [SWinR 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_inner_0RB1LC_0LC1RD_1RB1LA_0RB0RB : srun tm false true chn_0RB1LC_0LC1RD_1RB1LA_0RB0RB AI0_0RB1LC_0LC1RD_1RB1LA_0RB0RB = Some (AI1_0RB1LC_0LC1RD_1RB1LA_0RB0RB, 4, 8).
