(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB1LC_0LC1RD_1RB1LA_0RB0RB : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
