  exists (4 * j + 8), (cden (Ip q0 ++ [S0]) [] j A1_0RB1LC_0LC1RD_1RB1LA_0RB0RB).
  split; [lia|]. split; [| exact (gei_0RB1LC_0LC1RD_1RB1LA_0RB0RB p j q0 E)].
  rewrite (gsi_0RB1LC_0LC1RD_1RB1LA_0RB0RB p j q0 E).
  exact (srun_sound tm false true chi_0RB1LC_0LC1RD_1RB1LA_0RB0RB A0_0RB1LC_0LC1RD_1RB1LA_0RB0RB A1_0RB1LC_0LC1RD_1RB1LA_0RB0RB 4 8
           run_int_0RB1LC_0LC1RD_1RB1LA_0RB0RB (Ip q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_0RB1LC_0LC1RD_1RB1LA_0RB0RB : forall p j, cview p = (S j, None) ->
