Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB1LC_0LC1RD_1RB1LA_0RB0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LC_0LC1RD_1RB1LA_0RB0RB) = lift (Cc (Pos.succ p)).
