(** ** The lap *)

Lemma lap_0RB1LC_0RC1RD_1LA0RB_0LA1RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
