(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_0RB1LC_1LA0LC_1RD0RD_1RB0LA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] 0 Z0_0RB1LC_1LA0LC_1RD0RD_1RB0LA /\
  cden (Kp q0 ++ [S0]) [] 0 Z1_0RB1LC_1LA0LC_1RD0RD_1RB0LA = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (KpCounter.cview_some_K p 0 q0 E) as (H1 & H2).
  unfold Cc_0RB1LC_1LA0LC_1RD0RD_1RB0LA, cden, Z0_0RB1LC_1LA0LC_1RD0RD_1RB0LA, Z1_0RB1LC_1LA0LC_1RD0RD_1RB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_0RB1LC_1LA0LC_1RD0RD_1RB0LA : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j P0_0RB1LC_1LA0LC_1RD0RD_1RB0LA /\
  cden (Kp q0 ++ [S0]) [] j P1_0RB1LC_1LA0LC_1RD0RD_1RB0LA = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (KpCounter.cview_some_K p (S j) q0 E) as (H1 & H2).
  unfold Cc_0RB1LC_1LA0LC_1RD0RD_1RB0LA, cden, P0_0RB1LC_1LA0LC_1RD0RD_1RB0LA, P1_0RB1LC_1LA0LC_1RD0RD_1RB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1LC_1LA0LC_1RD0RD_1RB0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_0RB1LC_1LA0LC_1RD0RD_1RB0LA p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_0RB1LC_1LA0LC_1RD0RD_1RB0LA Z0_0RB1LC_1LA0LC_1RD0RD_1RB0LA Z1_0RB1LC_1LA0LC_1RD0RD_1RB0LA 0 2
               run_z_0RB1LC_1LA0LC_1RD0RD_1RB0LA (Kp q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_0RB1LC_1LA0LC_1RD0RD_1RB0LA p j' q0 E) as (HA & HB).
    exists (6 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_0RB1LC_1LA0LC_1RD0RD_1RB0LA P0_0RB1LC_1LA0LC_1RD0RD_1RB0LA P1_0RB1LC_1LA0LC_1RD0RD_1RB0LA 6 8
               run_p_0RB1LC_1LA0LC_1RD0RD_1RB0LA (Kp q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_0RB1LC_1LA0LC_1RD0RD_1RB0LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1LC_1LA0LC_1RD0RD_1RB0LA.
