    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB1LC_1LA1LC_0RD0LA_1LB1RD : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S1 DR StC
  | StB, S0 => mk S1 DR StA | StB, S1 => mk S1 DR StC
  | StC, S0 => mk S0 DL StD | StC, S1 => mk S0 DR StA
  | StD, S0 => mk S1 DR StB | StD, S1 => mk S1 DL StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1LC_1LA1LC_0RD0LA_1LB1RD : list Instr := [].
Definition tmw_0RB1LC_1LA1LC_0RD0LA_1LB1RD : TM := tm_wrap_trs tmm_0RB1LC_1LA1LC_0RD0LA_1LB1RD pins_0RB1LC_1LA1LC_0RD0LA_1LB1RD.
Local Notation tm := tmw_0RB1LC_1LA1LC_0RD0LA_1LB1RD.

Lemma mirror_ok_0RB1LC_1LA1LC_0RD0LA_1LB1RD : mirror_tm tm_0RB1LC_1LA1LC_0RD0LA_1LB1RD = tmm_0RB1LC_1LA1LC_0RD0LA_1LB1RD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_0RB1LC_1LA1LC_0RD0LA_1LB1RD (p : positive) : cconf := (StC, (Ap_Alph_10_11_11 p ++ [S0], S0, [])).
Local Notation Cc := Cc_0RB1LC_1LA1LC_0RD0LA_1LB1RD.

(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_0RB1LC_1LA1LC_0RD0LA_1LB1RD : sconf := mkC StC (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_0RB1LC_1LA1LC_0RD0LA_1LB1RD : sconf := mkC StC (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
