(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB1LC_1LA1LC_0RD0LA_1LB1RD : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_0RB1LC_1LA1LC_0RD0LA_1LB1RD : list lstep := [SWinR 4; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 1; SRotL 1; SFoldL 1].

Lemma run_exit_0RB1LC_1LA1LC_0RD0LA_1LB1RD : srun tm true true che_0RB1LC_1LA1LC_0RD0LA_1LB1RD BE0_0RB1LC_1LA1LC_0RD0LA_1LB1RD = Some (B1_0RB1LC_1LA1LC_0RD0LA_1LB1RD, 4, 11).
