Definition Cin_0RB1LC_1LA1RB_0LA1LD_0RD0LA (v : positive) : cconf := (StB, (Ap_Alph_110_111_1 v ++ [S1;S1], S0, [])).
Local Notation Cin := Cin_0RB1LC_1LA1RB_0LA1LD_0RD0LA.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB1LC_1LA1RB_0LA1LD_0RD0LA : forall n, Ap_Alph_110_111_1 (pow2 n) = rep [S1;S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB1LC_1LA1RB_0LA1LD_0RD0LA : sconf := mkC StB (mkS [] [S1;S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AI1_0RB1LC_1LA1RB_0LA1LD_0RD0LA : sconf := mkC StB (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chn_0RB1LC_1LA1RB_0LA1LD_0RD0LA : list lstep := [SWinR 2; SCycL 3 0; SWin 6; SCycR 3; SWin 2].

Lemma run_inner_0RB1LC_1LA1RB_0LA1LD_0RD0LA : srun tm false true chn_0RB1LC_1LA1RB_0LA1LD_0RD0LA AI0_0RB1LC_1LA1RB_0LA1LD_0RD0LA = Some (AI1_0RB1LC_1LA1RB_0LA1LD_0RD0LA, 6, 10).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB1LC_1LA1RB_0LA1LD_0RD0LA : sconf := mkC StB (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chb_0RB1LC_1LA1RB_0LA1LD_0RD0LA : list lstep := [SWinR 2; SCycL 3 0; SWin 6; SCycR 3; SWin 2].

Lemma run_boot_0RB1LC_1LA1RB_0LA1LD_0RD0LA : srun tm true true chb_0RB1LC_1LA1RB_0LA1LD_0RD0LA B0_0RB1LC_1LA1RB_0LA1LD_0RD0LA = Some (BB1_0RB1LC_1LA1RB_0LA1LD_0RD0LA, 6, 10).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB1LC_1LA1RB_0LA1LD_0RD0LA : sconf := mkC StB (mkS [] [S1;S1;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_0RB1LC_1LA1RB_0LA1LD_0RD0LA : list lstep := [SWinR 2; SCycL 3 0; SWin 3; SWinL 5; SCycR 3; SWin 1; SWinR 2; SRotL 2; SFoldL 1].

Lemma run_exit_0RB1LC_1LA1RB_0LA1LD_0RD0LA : srun tm true true che_0RB1LC_1LA1RB_0LA1LD_0RD0LA BE0_0RB1LC_1LA1RB_0LA1LD_0RD0LA = Some (B1_0RB1LC_1LA1RB_0LA1LD_0RD0LA, 6, 13).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB1LC_1LA1RB_0LA1LD_0RD0LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_101_111_11 q0 ++ [S0]) [] j A0_0RB1LC_1LA1RB_0LA1LD_0RD0LA.
Proof.
  intros p j q0 E. destruct (Alph_101_111_11.cview_some_Alph_101_111_11 p j q0 E) as (H1 & _).
  unfold Cc_0RB1LC_1LA1RB_0LA1LD_0RD0LA, cden, A0_0RB1LC_1LA1RB_0LA1LD_0RD0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_0RB1LC_1LA1RB_0LA1LD_0RD0LA : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_101_111_11 q0 ++ [S0]) [] j A1_0RB1LC_1LA1RB_0LA1LD_0RD0LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_101_111_11.cview_some_Alph_101_111_11 p j q0 E) as (_ & H2).
  unfold Cc_0RB1LC_1LA1RB_0LA1LD_0RD0LA, cden, A1_0RB1LC_1LA1RB_0LA1LD_0RD0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1LC_1LA1RB_0LA1LD_0RD0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (6 * j + 10), (cden (Ap_Alph_101_111_11 q0 ++ [S0]) [] j A1_0RB1LC_1LA1RB_0LA1LD_0RD0LA).
  split; [lia|]. split; [| exact (gei_0RB1LC_1LA1RB_0LA1LD_0RD0LA p j q0 E)].
  rewrite (gsi_0RB1LC_1LA1RB_0LA1LD_0RD0LA p j q0 E).
  exact (srun_sound tm false true chi_0RB1LC_1LA1RB_0LA1LD_0RD0LA A0_0RB1LC_1LA1RB_0LA1LD_0RD0LA A1_0RB1LC_1LA1RB_0LA1LD_0RD0LA 6 10
           run_int_0RB1LC_1LA1RB_0LA1LD_0RD0LA (Ap_Alph_101_111_11 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_0RB1LC_1LA1RB_0LA1LD_0RD0LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1LC_1LA1RB_0LA1LD_0RD0LA.
Proof.
  intros p j E. destruct (Alph_101_111_11.cview_none_Alph_101_111_11 p j E) as (H1 & _).
  unfold Cc_0RB1LC_1LA1RB_0LA1LD_0RD0LA, cden, B0_0RB1LC_1LA1RB_0LA1LD_0RD0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB1LC_1LA1RB_0LA1LD_0RD0LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB1LC_1LA1RB_0LA1LD_0RD0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LC_1LA1RB_0LA1LD_0RD0LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_101_111_11.cview_none_Alph_101_111_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB1LC_1LA1RB_0LA1LD_0RD0LA
             = (StB, (rep [S1;S0;S1] (S j) ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, B1_0RB1LC_1LA1RB_0LA1LD_0RD0LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S1;S0;S1] (S j) ++ [S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB1LC_1LA1RB_0LA1LD_0RD0LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_0RB1LC_1LA1RB_0LA1LD_0RD0LA. reflexivity.
Qed.

Lemma gsn_0RB1LC_1LA1RB_0LA1LD_0RD0LA : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i AI0_0RB1LC_1LA1RB_0LA1LD_0RD0LA.
Proof.
  intros v i q0 E. destruct (Alph_110_111_1.cview_some_Alph_110_111_1 v i q0 E) as (H1 & _).
  unfold Cin_0RB1LC_1LA1RB_0LA1LD_0RD0LA, cden, AI0_0RB1LC_1LA1RB_0LA1LD_0RD0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_0RB1LC_1LA1RB_0LA1LD_0RD0LA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i AI1_0RB1LC_1LA1RB_0LA1LD_0RD0LA) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (Alph_110_111_1.cview_some_Alph_110_111_1 v i q0 E) as (_ & H2).
  unfold Cin_0RB1LC_1LA1RB_0LA1LD_0RD0LA, cden, AI1_0RB1LC_1LA1RB_0LA1LD_0RD0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB1LC_1LA1RB_0LA1LD_0RD0LA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 10), (cden (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i AI1_0RB1LC_1LA1RB_0LA1LD_0RD0LA).
  split; [lia|]. split; [| exact (gen_0RB1LC_1LA1RB_0LA1LD_0RD0LA v i q0 E)].
  rewrite (gsn_0RB1LC_1LA1RB_0LA1LD_0RD0LA v i q0 E).
  exact (srun_sound tm false true chn_0RB1LC_1LA1RB_0LA1LD_0RD0LA AI0_0RB1LC_1LA1RB_0LA1LD_0RD0LA AI1_0RB1LC_1LA1RB_0LA1LD_0RD0LA 6 10
           run_inner_0RB1LC_1LA1RB_0LA1LD_0RD0LA (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/1
    trailing blanks. *)
Lemma gbo_0RB1LC_1LA1RB_0LA1LD_0RD0LA : forall j, lift (cden [] [] j BB1_0RB1LC_1LA1RB_0LA1LD_0RD0LA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB1LC_1LA1RB_0LA1LD_0RD0LA = (StB, (rep [S1;S1;S0] j ++ [S1;S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_0RB1LC_1LA1RB_0LA1LD_0RD0LA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S1;S0] j ++ [S1;S1;S1], S0, []))).
  { unfold Cin_0RB1LC_1LA1RB_0LA1LD_0RD0LA. rewrite epow2_0RB1LC_1LA1RB_0LA1LD_0RD0LA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB1LC_1LA1RB_0LA1LD_0RD0LA. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB1LC_1LA1RB_0LA1LD_0RD0LA : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB1LC_1LA1RB_0LA1LD_0RD0LA.
Proof.
  intro j.
  destruct (Alph_110_111_1.cview_none_Alph_110_111_1 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB1LC_1LA1RB_0LA1LD_0RD0LA, cden, BE0_0RB1LC_1LA1RB_0LA1LD_0RD0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB1LC_1LA1RB_0LA1LD_0RD0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_0RB1LC_1LA1RB_0LA1LD_0RD0LA. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1LC_1LA1RB_0LA1LD_0RD0LA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1LC_1LA1RB_0LA1LD_0RD0LA p (pow2 j)).
  - exists (6 * j + 10), (cden [] [] j BB1_0RB1LC_1LA1RB_0LA1LD_0RD0LA).
    split; [lia|]. split; [| exact (gbo_0RB1LC_1LA1RB_0LA1LD_0RD0LA j)].
    rewrite (gso_0RB1LC_1LA1RB_0LA1LD_0RD0LA p j E).
    exact (srun_sound tm true true chb_0RB1LC_1LA1RB_0LA1LD_0RD0LA B0_0RB1LC_1LA1RB_0LA1LD_0RD0LA BB1_0RB1LC_1LA1RB_0LA1LD_0RD0LA 6 10
             run_boot_0RB1LC_1LA1RB_0LA1LD_0RD0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 13), (cden [] [] j B1_0RB1LC_1LA1RB_0LA1LD_0RD0LA).
    split; [| exact (geo_0RB1LC_1LA1RB_0LA1LD_0RD0LA p j E)].
    rewrite (gxi_0RB1LC_1LA1RB_0LA1LD_0RD0LA j).
    exact (srun_sound tm true true che_0RB1LC_1LA1RB_0LA1LD_0RD0LA BE0_0RB1LC_1LA1RB_0LA1LD_0RD0LA B1_0RB1LC_1LA1RB_0LA1LD_0RD0LA 6 13
             run_exit_0RB1LC_1LA1RB_0LA1LD_0RD0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB1LC_1LA1RB_0LA1LD_0RD0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1LC_1LA1RB_0LA1LD_0RD0LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB1LC_1LA1RB_0LA1LD_0RD0LA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LC_1LA1RB_0LA1LD_0RD0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 8.
  assert (H : match csteps tm 8 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 8 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1LC_1LA1RB_0LA1LD_0RD0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1LC_1LA1RB_0LA1LD_0RD0LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB1LC_1LA1RB_0LA1LD_0RD0LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1LC_1LA1RB_0LA1LD_0RD0LA p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_0RB1LC_1LA1RB_0LA1LD_0RD0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_0RB1LC_1LA1RB_0LA1LD_0RD0LA = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_0RB1LC_1LA1RB_0LA1LD_0RD0LA p j (Ap_Alph_101_111_11 q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_0RB1LC_1LA1RB_0LA1LD_0RD0LA p j q0 E)].
Qed.

(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB1LC_1LA1RB_0LA1LD_0RD0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB1LC_1LA1RB_0LA1LD_0RD0LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
