  exists (4 * j + 6), (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_0RB1LC_1LA1RB_0LD0LA_0RA___).
  split; [lia|]. split; [| exact (gei_0RB1LC_1LA1RB_0LD0LA_0RA___ p j q0 E)].
  rewrite (gsi_0RB1LC_1LA1RB_0LD0LA_0RA___ p j q0 E).
  exact (srun_sound tm false true chi_0RB1LC_1LA1RB_0LD0LA_0RA___ A0_0RB1LC_1LA1RB_0LD0LA_0RA___ A1_0RB1LC_1LA1RB_0LD0LA_0RA___ 4 6
           run_int_0RB1LC_1LA1RB_0LD0LA_0RA___ (Ap_Alph_10_11_11 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_0RB1LC_1LA1RB_0LD0LA_0RA___ : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1LC_1LA1RB_0LD0LA_0RA___.
