Proof. exact lapi_0RB1LC_1LA1RB_0LD0LA_0RA___. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1LC_1LA1RB_0LD0LA_0RA___ : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1LC_1LA1RB_0LD0LA_0RA___ p (pow2 j)).
  - exists (4 * j + 7), (cden [] [] j BB1_0RB1LC_1LA1RB_0LD0LA_0RA___).
    split; [lia|]. split; [| exact (gbo_0RB1LC_1LA1RB_0LD0LA_0RA___ j)].
    rewrite (gso_0RB1LC_1LA1RB_0LD0LA_0RA___ p j E).
    exact (srun_sound tm true true chb_0RB1LC_1LA1RB_0LD0LA_0RA___ B0_0RB1LC_1LA1RB_0LD0LA_0RA___ BB1_0RB1LC_1LA1RB_0LD0LA_0RA___ 4 7
             run_boot_0RB1LC_1LA1RB_0LD0LA_0RA___ [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 11), (cden [] [] j B1_0RB1LC_1LA1RB_0LD0LA_0RA___).
    split; [| exact (geo_0RB1LC_1LA1RB_0LD0LA_0RA___ p j E)].
    rewrite (gxi_0RB1LC_1LA1RB_0LD0LA_0RA___ j).
