Lemma lapin_0RB1LC_1LA1RB_0LD0LA_0RD1RB : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 8), (cden (Ip q0 ++ [S1]) [] i AI1_0RB1LC_1LA1RB_0LD0LA_0RD1RB).
  split; [lia|]. split; [| exact (gen_0RB1LC_1LA1RB_0LD0LA_0RD1RB v i q0 E)].
  rewrite (gsn_0RB1LC_1LA1RB_0LD0LA_0RD1RB v i q0 E).
  exact (srun_sound tm false true chn_0RB1LC_1LA1RB_0LD0LA_0RD1RB AI0_0RB1LC_1LA1RB_0LD0LA_0RD1RB AI1_0RB1LC_1LA1RB_0LD0LA_0RD1RB 4 8
           run_inner_0RB1LC_1LA1RB_0LD0LA_0RD1RB (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
