Lemma firex_0RB1LC_1LA1RB_0LD1LD_0RD0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB1LC_1LA1RB_0LD1LD_0RD0LA = Some t ->
