Lemma gz_0RB1LC_1LA1RB_0RB0LD_0RB1LC : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z0_0RB1LC_1LA1RB_0RB0LD_0RB1LC /\
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z1_0RB1LC_1LA1RB_0RB0LD_0RB1LC = Cc (Pos.succ p).
