  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (6 * j + 4), (cden [] [] j BB1_0RB1LC_1LA1RB_0RB1LD_0RA0LA).
      split; [lia|]. split; [| exact (gbo_0RB1LC_1LA1RB_0RB1LD_0RA0LA j)].
