(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB1LC_1LA1RB_0RB1LD_1RC0LA : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB1LC_1LA1RB_0RB1LD_1RC0LA.
Proof.
  intro j.
  destruct (Alph_101_111_1.cview_none_Alph_101_111_1 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB1LC_1LA1RB_0RB1LD_1RC0LA, cden, BE0_0RB1LC_1LA1RB_0RB1LD_1RC0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB1LC_1LA1RB_0RB1LD_1RC0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB1LC_1LA1RB_0RB1LD_1RC0LA p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1LC_1LA1RB_0RB1LD_1RC0LA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1LC_1LA1RB_0RB1LD_1RC0LA p (pow2 j)).
  - exists (6 * j + 4), (cden [] [] j BB1_0RB1LC_1LA1RB_0RB1LD_1RC0LA).
    split; [lia|]. split; [| exact (gbo_0RB1LC_1LA1RB_0RB1LD_1RC0LA j)].
    rewrite (gso_0RB1LC_1LA1RB_0RB1LD_1RC0LA p j E).
    exact (srun_sound tm true true chb_0RB1LC_1LA1RB_0RB1LD_1RC0LA B0_0RB1LC_1LA1RB_0RB1LD_1RC0LA BB1_0RB1LC_1LA1RB_0RB1LD_1RC0LA 6 4
             run_boot_0RB1LC_1LA1RB_0RB1LD_1RC0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 9), (cden [] [] j B1_0RB1LC_1LA1RB_0RB1LD_1RC0LA).
    split; [| exact (geo_0RB1LC_1LA1RB_0RB1LD_1RC0LA p j E)].
    rewrite (gxi_0RB1LC_1LA1RB_0RB1LD_1RC0LA j).
    exact (srun_sound tm true true che_0RB1LC_1LA1RB_0RB1LD_1RC0LA BE0_0RB1LC_1LA1RB_0RB1LD_1RC0LA B1_0RB1LC_1LA1RB_0RB1LD_1RC0LA 6 9
             run_exit_0RB1LC_1LA1RB_0RB1LD_1RC0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.

(** A state firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma visx_0RB1LC_1LA1RB_0RB1LD_1RC0LA : forall (l : list lstep) (q : St),
  srun_st tm true true l BE0_0RB1LC_1LA1RB_0RB1LD_1RC0LA = Some q ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ fst e = q.
Proof.
  intros l q Hst p j E.
  apply (vis_via_fill tm Cc Cin lapin_0RB1LC_1LA1RB_0RB1LD_1RC0LA q p (pow2 j)).
  - exists (6 * j + 4), (cden [] [] j BB1_0RB1LC_1LA1RB_0RB1LD_1RC0LA). split;
      [| exact (gbo_0RB1LC_1LA1RB_0RB1LD_1RC0LA j)].
    rewrite (gso_0RB1LC_1LA1RB_0RB1LD_1RC0LA p j E).
    exact (srun_sound tm true true chb_0RB1LC_1LA1RB_0RB1LD_1RC0LA B0_0RB1LC_1LA1RB_0RB1LD_1RC0LA BB1_0RB1LC_1LA1RB_0RB1LD_1RC0LA 6 4
             run_boot_0RB1LC_1LA1RB_0RB1LD_1RC0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (vis_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (vis_of_run tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB1LC_1LA1RB_0RB1LD_1RC0LA xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB1LC_1LA1RB_0RB1LD_1RC0LA j)].
Qed.



(** ** The lap *)

Lemma lap_0RB1LC_1LA1RB_0RB1LD_1RC0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1LC_1LA1RB_0RB1LD_1RC0LA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB1LC_1LA1RB_0RB1LD_1RC0LA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LC_1LA1RB_0RB1LD_1RC0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 2.
  assert (H : match csteps tm 2 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 2 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
