Lemma fireo_0RB1LC_1LA1RB_0RB1LD_1RC0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1LC_1LA1RB_0RB1LD_1RC0LA = Some t ->
