    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1LC_1LA1RB_0RB1LD_1RC0LA p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB1LC_1LA1RB_0RB1LD_1RC0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB1LC_1LA1RB_0RB1LD_1RC0LA = Some t ->
