    [LapCertGlue.reach_ovf]); the overflow branch closes one blank short of
    the anchor tail, hence up to [lift].

    Differentially validated against the raw simulator on BOTH branches --
    step counts AND exact configurations -- for 192 interior anchors (interior); 6 overflow phases, j = 2..7 (492 inner laps, 2 counts each) (nested overflow).
    Axiom footprint: [functional_extensionality_dep] (via [CTape.lift]). *)
Import Arith Lia Bool List PArith Wellfounded.
Import BBB4_Statement CTape Mirror.
Import FunctionalExtensionality.
Import WTape LapGlue LapGlueQH LapGlueAbs
                                  MonoCounter JpCounter Alph_011_111_1 LapCertGlue LapCertGlueLift IXPGadgets NestedLap NestedLapLift NestedLap2 Alph_101_111_1 Alph_110_111_1.
Import TNF_QH.
Import LapDecider.
Import BBBT4_Statement.
Import WrapTr.
Import AnchorVisitsTr.
Import LapGlueTr.
Import TNF_QHTr.
Import ListNotations.

Definition mk_0RB1LC_1LA1RB_0RC1LD_0RB0LA (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_0RB1LC_1LA1RB_0RC1LD_0RB0LA.

(** 0RB1LC_1LA1RB_0RC1LD_0RB0LA *)
(** 0RB1LC_1LA1RB_0RC1LD_0RB0LA -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB1LC_1LA1RB_0RC1LD_0RB0LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S1 DL StC
  | StB, S0 => mk S1 DL StA | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S0 DR StC | StC, S1 => mk S1 DL StD
  | StD, S0 => mk S0 DR StB | StD, S1 => mk S0 DL StA end.

(** Its mirror 0LB1RC_1RA1LB_0LC1RD_0LB0RA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB1LC_1LA1RB_0RC1LD_0RB0LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S1 DR StC
  | StB, S0 => mk S1 DR StA | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S0 DL StC | StC, S1 => mk S1 DR StD
  | StD, S0 => mk S0 DL StB | StD, S1 => mk S0 DR StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1LC_1LA1RB_0RC1LD_0RB0LA : list Instr := [].
Definition tmw_0RB1LC_1LA1RB_0RC1LD_0RB0LA : TM := tm_wrap_trs tmm_0RB1LC_1LA1RB_0RC1LD_0RB0LA pins_0RB1LC_1LA1RB_0RC1LD_0RB0LA.
Local Notation tm := tmw_0RB1LC_1LA1RB_0RC1LD_0RB0LA.

Lemma mirror_ok_0RB1LC_1LA1RB_0RC1LD_0RB0LA : mirror_tm tm_0RB1LC_1LA1RB_0RC1LD_0RB0LA = tmm_0RB1LC_1LA1RB_0RC1LD_0RB0LA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_0RB1LC_1LA1RB_0RC1LD_0RB0LA (p : positive) : cconf := (StA, (Ap_Alph_011_111_1 p ++ [S0], S0, [])).
Local Notation Cc := Cc_0RB1LC_1LA1RB_0RC1LD_0RB0LA.

(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_0RB1LC_1LA1RB_0RC1LD_0RB0LA : sconf := mkC StA (mkS [S0;S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_0RB1LC_1LA1RB_0RC1LD_0RB0LA : sconf := mkC StA (mkS [S1;S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition chz_0RB1LC_1LA1RB_0RC1LD_0RB0LA : list lstep := [SWin 2].

Lemma run_z_0RB1LC_1LA1RB_0RC1LD_0RB0LA : srun tm false true chz_0RB1LC_1LA1RB_0RC1LD_0RB0LA Z0_0RB1LC_1LA1RB_0RC1LD_0RB0LA = Some (Z1_0RB1LC_1LA1RB_0RC1LD_0RB0LA, 0, 2).
Proof. vm_compute. reflexivity. Qed.

(** j = S j': one copy of the unit sits in the PREFIX, so the head always has
    a concrete cell to step onto. *)
Definition P0_0RB1LC_1LA1RB_0RC1LD_0RB0LA : sconf := mkC StA (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S0;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition P1_0RB1LC_1LA1RB_0RC1LD_0RB0LA : sconf := mkC StA (mkS [S0;S1;S1] [S0;S1;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chp_0RB1LC_1LA1RB_0RC1LD_0RB0LA : list lstep := [SWin 3; SCycL 3 0; SWin 2; SCycR 3; SWin 3].

Lemma run_p_0RB1LC_1LA1RB_0RC1LD_0RB0LA : srun tm false true chp_0RB1LC_1LA1RB_0RC1LD_0RB0LA P0_0RB1LC_1LA1RB_0RC1LD_0RB0LA = Some (P1_0RB1LC_1LA1RB_0RC1LD_0RB0LA, 6, 8).
Proof. vm_compute. reflexivity. Qed.

Definition B0_0RB1LC_1LA1RB_0RC1LD_0RB0LA : sconf := mkC StA (mkS [] [S1;S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_0RB1LC_1LA1RB_0RC1LD_0RB0LA : sconf := mkC StA (mkS [] [S0;S1;S1] 1 1 [S1]) S0 (mkS [] [] 0 0 []).
(** ** The FIRST INNER anchor family -- Ap_Alph_101_111_1 at StC *)
Definition Cin_0RB1LC_1LA1RB_0RC1LD_0RB0LA (v : positive) : cconf := (StC, (Ap_Alph_101_111_1 v ++ [S1], S0, [])).
Local Notation Cin := Cin_0RB1LC_1LA1RB_0RC1LD_0RB0LA.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB1LC_1LA1RB_0RC1LD_0RB0LA : forall n, Ap_Alph_101_111_1 (pow2 n) = rep [S1;S0;S1] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB1LC_1LA1RB_0RC1LD_0RB0LA : sconf := mkC StC (mkS [] [S1;S1;S1] 1 0 [S1;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition AI1_0RB1LC_1LA1RB_0RC1LD_0RB0LA : sconf := mkC StC (mkS [] [S1;S0;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chn_0RB1LC_1LA1RB_0RC1LD_0RB0LA : list lstep := [SRotL 1; SWin 3; SCycL 3 0; SWin 2; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_inner_0RB1LC_1LA1RB_0RC1LD_0RB0LA : srun tm false true chn_0RB1LC_1LA1RB_0RC1LD_0RB0LA AI0_0RB1LC_1LA1RB_0RC1LD_0RB0LA = Some (AI1_0RB1LC_1LA1RB_0RC1LD_0RB0LA, 6, 6).
Proof. vm_compute. reflexivity. Qed.

(** ** The SECOND INNER anchor family -- Ap_Alph_110_111_1 at StD *)
Definition Cin2_0RB1LC_1LA1RB_0RC1LD_0RB0LA (v : positive) : cconf := (StD, (Ap_Alph_110_111_1 v ++ [S1;S1], S0, [])).
Local Notation Cin2 := Cin2_0RB1LC_1LA1RB_0RC1LD_0RB0LA.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow22_0RB1LC_1LA1RB_0RC1LD_0RB0LA : forall n, Ap_Alph_110_111_1 (pow2 n) = rep [S1;S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI20_0RB1LC_1LA1RB_0RC1LD_0RB0LA : sconf := mkC StD (mkS [] [S1;S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AI21_0RB1LC_1LA1RB_0RC1LD_0RB0LA : sconf := mkC StD (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chn2_0RB1LC_1LA1RB_0RC1LD_0RB0LA : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_inner2_0RB1LC_1LA1RB_0RC1LD_0RB0LA : srun tm false true chn2_0RB1LC_1LA1RB_0RC1LD_0RB0LA AI20_0RB1LC_1LA1RB_0RC1LD_0RB0LA = Some (AI21_0RB1LC_1LA1RB_0RC1LD_0RB0LA, 6, 6).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB1LC_1LA1RB_0RC1LD_0RB0LA : sconf := mkC StC (mkS [] [S1;S0;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chb_0RB1LC_1LA1RB_0RC1LD_0RB0LA : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_boot_0RB1LC_1LA1RB_0RC1LD_0RB0LA : srun tm true true chb_0RB1LC_1LA1RB_0RC1LD_0RB0LA B0_0RB1LC_1LA1RB_0RC1LD_0RB0LA = Some (BB1_0RB1LC_1LA1RB_0RC1LD_0RB0LA, 6, 4).
Proof. vm_compute. reflexivity. Qed.

(** *** shift: count 1's all-ones fill -> count 2's anchor.
    WAVE18 section 4c -- "count 8->15, shift, count 8->15 again". *)
Definition BM0_0RB1LC_1LA1RB_0RC1LD_0RB0LA : sconf := mkC StC (mkS [] [S1;S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition BM1_0RB1LC_1LA1RB_0RC1LD_0RB0LA : sconf := mkC StD (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chm_0RB1LC_1LA1RB_0RC1LD_0RB0LA : list lstep := [SRotL 1; SWin 3; SCycL 3 0; SWin 1; SWinL 3; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_shift_0RB1LC_1LA1RB_0RC1LD_0RB0LA : srun tm true true chm_0RB1LC_1LA1RB_0RC1LD_0RB0LA BM0_0RB1LC_1LA1RB_0RC1LD_0RB0LA = Some (BM1_0RB1LC_1LA1RB_0RC1LD_0RB0LA, 6, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB1LC_1LA1RB_0RC1LD_0RB0LA : sconf := mkC StD (mkS [] [S1;S1;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_0RB1LC_1LA1RB_0RC1LD_0RB0LA : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SWinL 4; SCycR 3; SWin 1; SRotL 2; SFoldL 1].

Lemma run_exit_0RB1LC_1LA1RB_0RC1LD_0RB0LA : srun tm true true che_0RB1LC_1LA1RB_0RC1LD_0RB0LA BE0_0RB1LC_1LA1RB_0RC1LD_0RB0LA = Some (B1_0RB1LC_1LA1RB_0RC1LD_0RB0LA, 6, 8).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_0RB1LC_1LA1RB_0RC1LD_0RB0LA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z0_0RB1LC_1LA1RB_0RC1LD_0RB0LA /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z1_0RB1LC_1LA1RB_0RC1LD_0RB0LA = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_0RB1LC_1LA1RB_0RC1LD_0RB0LA, cden, Z0_0RB1LC_1LA1RB_0RC1LD_0RB0LA, Z1_0RB1LC_1LA1RB_0RC1LD_0RB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_0RB1LC_1LA1RB_0RC1LD_0RB0LA : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P0_0RB1LC_1LA1RB_0RC1LD_0RB0LA /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P1_0RB1LC_1LA1RB_0RC1LD_0RB0LA = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p (S j) q0 E) as (H1 & H2).
  unfold Cc_0RB1LC_1LA1RB_0RC1LD_0RB0LA, cden, P0_0RB1LC_1LA1RB_0RC1LD_0RB0LA, P1_0RB1LC_1LA1RB_0RC1LD_0RB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1LC_1LA1RB_0RC1LD_0RB0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_0RB1LC_1LA1RB_0RC1LD_0RB0LA p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_0RB1LC_1LA1RB_0RC1LD_0RB0LA Z0_0RB1LC_1LA1RB_0RC1LD_0RB0LA Z1_0RB1LC_1LA1RB_0RC1LD_0RB0LA 0 2
               run_z_0RB1LC_1LA1RB_0RC1LD_0RB0LA (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_0RB1LC_1LA1RB_0RC1LD_0RB0LA p j' q0 E) as (HA & HB).
    exists (6 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_0RB1LC_1LA1RB_0RC1LD_0RB0LA P0_0RB1LC_1LA1RB_0RC1LD_0RB0LA P1_0RB1LC_1LA1RB_0RC1LD_0RB0LA 6 8
               run_p_0RB1LC_1LA1RB_0RC1LD_0RB0LA (Ap_Alph_011_111_1 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_0RB1LC_1LA1RB_0RC1LD_0RB0LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1LC_1LA1RB_0RC1LD_0RB0LA.
Proof.
  intros p j E. destruct (Alph_011_111_1.cview_none_Alph_011_111_1 p j E) as (H1 & _).
  unfold Cc_0RB1LC_1LA1RB_0RC1LD_0RB0LA, cden, B0_0RB1LC_1LA1RB_0RC1LD_0RB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB1LC_1LA1RB_0RC1LD_0RB0LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB1LC_1LA1RB_0RC1LD_0RB0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LC_1LA1RB_0RC1LD_0RB0LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_011_111_1.cview_none_Alph_011_111_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB1LC_1LA1RB_0RC1LD_0RB0LA
             = (StA, (rep [S0;S1;S1] (S j) ++ [S1], S0, []))).
  { unfold cden, B1_0RB1LC_1LA1RB_0RC1LD_0RB0LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StA, ((rep [S0;S1;S1] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB1LC_1LA1RB_0RC1LD_0RB0LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB1LC_1LA1RB_0RC1LD_0RB0LA. reflexivity.
Qed.

Lemma gsn_0RB1LC_1LA1RB_0RC1LD_0RB0LA : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI0_0RB1LC_1LA1RB_0RC1LD_0RB0LA.
Proof.
  intros v i q0 E. destruct (Alph_101_111_1.cview_some_Alph_101_111_1 v i q0 E) as (H1 & _).
  unfold Cin_0RB1LC_1LA1RB_0RC1LD_0RB0LA, cden, AI0_0RB1LC_1LA1RB_0RC1LD_0RB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_0RB1LC_1LA1RB_0RC1LD_0RB0LA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI1_0RB1LC_1LA1RB_0RC1LD_0RB0LA) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (Alph_101_111_1.cview_some_Alph_101_111_1 v i q0 E) as (_ & H2).
  unfold Cin_0RB1LC_1LA1RB_0RC1LD_0RB0LA, cden, AI1_0RB1LC_1LA1RB_0RC1LD_0RB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB1LC_1LA1RB_0RC1LD_0RB0LA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 6), (cden (Ap_Alph_101_111_1 q0 ++ [S1]) [] i AI1_0RB1LC_1LA1RB_0RC1LD_0RB0LA).
  split; [lia|]. split; [| exact (gen_0RB1LC_1LA1RB_0RC1LD_0RB0LA v i q0 E)].
  rewrite (gsn_0RB1LC_1LA1RB_0RC1LD_0RB0LA v i q0 E).
  exact (srun_sound tm false true chn_0RB1LC_1LA1RB_0RC1LD_0RB0LA AI0_0RB1LC_1LA1RB_0RC1LD_0RB0LA AI1_0RB1LC_1LA1RB_0RC1LD_0RB0LA 6 6
           run_inner_0RB1LC_1LA1RB_0RC1LD_0RB0LA (Ap_Alph_101_111_1 q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_0RB1LC_1LA1RB_0RC1LD_0RB0LA : forall j, lift (cden [] [] j BB1_0RB1LC_1LA1RB_0RC1LD_0RB0LA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB1LC_1LA1RB_0RC1LD_0RB0LA = (StC, (rep [S1;S0;S1] j ++ [S1;S1], S0, []))).
  { unfold cden, BB1_0RB1LC_1LA1RB_0RC1LD_0RB0LA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StC, (rep [S1;S0;S1] j ++ [S1;S1], S0, []))).
  { unfold Cin_0RB1LC_1LA1RB_0RC1LD_0RB0LA. rewrite epow2_0RB1LC_1LA1RB_0RC1LD_0RB0LA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
