  exact (srun_sound tm false true chn_0RB1LC_1LA1RB_0RC1LD_0RD0LA AI0_0RB1LC_1LA1RB_0RC1LD_0RD0LA AI1_0RB1LC_1LA1RB_0RC1LD_0RD0LA 6 10
           run_inner_0RB1LC_1LA1RB_0RC1LD_0RD0LA (Ap_Alph_101_111_1 q0 ++ [S1]) [] i
