(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_0RB1LC_1LA1RB_0RC1LD_0RD0LA : forall j, lift (cden [] [] j BB1_0RB1LC_1LA1RB_0RC1LD_0RD0LA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB1LC_1LA1RB_0RC1LD_0RD0LA = (StC, (rep [S1;S0;S1] j ++ [S1;S1], S0, []))).
  { unfold cden, BB1_0RB1LC_1LA1RB_0RC1LD_0RD0LA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StC, (rep [S1;S0;S1] j ++ [S1;S1], S0, []))).
  { unfold Cin_0RB1LC_1LA1RB_0RC1LD_0RD0LA. rewrite epow2_0RB1LC_1LA1RB_0RC1LD_0RD0LA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB1LC_1LA1RB_0RC1LD_0RD0LA. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB1LC_1LA1RB_0RC1LD_0RD0LA : forall j, Cin (fill (pow2 j)) = cden [] [] j BM0_0RB1LC_1LA1RB_0RC1LD_0RD0LA.
