    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_0RB1LC_1LA1RB_0RD0LA_0RC1LD. rewrite epow2_0RB1LC_1LA1RB_0RD0LA_0RC1LD.
