    apply (lap_of_run tm Cc true true cho_0RB1LC_1LA1RB_0RD0LA_1RA1LD B0_0RB1LC_1LA1RB_0RD0LA_1RA1LD B1_0RB1LC_1LA1RB_0RD0LA_1RA1LD 4 15 p j' [] []).
