  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB1LC_1LA1RB_0RD0LA_1RB0LC : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 8), (cden (Ip q0 ++ [S1]) [] i AI1_0RB1LC_1LA1RB_0RD0LA_1RB0LC).
  split; [lia|]. split; [| exact (gen_0RB1LC_1LA1RB_0RD0LA_1RB0LC v i q0 E)].
  rewrite (gsn_0RB1LC_1LA1RB_0RD0LA_1RB0LC v i q0 E).
  exact (srun_sound tm false true chn_0RB1LC_1LA1RB_0RD0LA_1RB0LC AI0_0RB1LC_1LA1RB_0RD0LA_1RB0LC AI1_0RB1LC_1LA1RB_0RD0LA_1RB0LC 4 8
           run_inner_0RB1LC_1LA1RB_0RD0LA_1RB0LC (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
